#include "ViewerRuntime.h"
namespace {
std::recursive_mutex storageMutex;
std::string ReadBytes(const fs::path& path,size_t limit=1024*1024){std::ifstream in(path,std::ios::binary);if(!in)throw std::runtime_error("storage read failed");in.seekg(0,std::ios::end);auto size=in.tellg();if(size<0||uint64_t(size)>limit)throw std::runtime_error("storage size limit");std::string bytes(size_t(size),'\0');in.seekg(0);if(!bytes.empty()&&!in.read(bytes.data(),std::streamsize(bytes.size())))throw std::runtime_error("storage read failed");return bytes;}
std::wstring Unique(){GUID g{};winrt::check_hresult(CoCreateGuid(&g));wchar_t s[40]{};StringFromGUID2(g,s,40);return s;}
void SafeDirectory(const fs::path& path){fs::create_directories(path);auto a=GetFileAttributesW(path.c_str());if(a==INVALID_FILE_ATTRIBUTES||!(a&FILE_ATTRIBUTE_DIRECTORY)||(a&FILE_ATTRIBUTE_REPARSE_POINT))throw std::runtime_error("redirected data folder");}
void NewBytes(const fs::path& path,const std::string& bytes){HANDLE h=CreateFileW(path.c_str(),GENERIC_WRITE,0,nullptr,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr);if(h==INVALID_HANDLE_VALUE)winrt::throw_last_error();bool ok=true;size_t at=0;while(at<bytes.size()){DWORD written=0;if(!WriteFile(h,bytes.data()+at,DWORD(std::min<size_t>(65536,bytes.size()-at)),&written,nullptr)||!written){ok=false;break;}at+=written;}if(ok)ok=FlushFileBuffers(h)!=FALSE;CloseHandle(h);if(!ok){DeleteFileW(path.c_str());throw std::runtime_error("storage write failed");}}
void Atomic(const fs::path& path,const std::string& bytes,bool replace=true){auto temp=path;temp+=L"."+Unique()+L".tmp";bool created=false;try{NewBytes(temp,bytes);created=true;if(ReadBytes(temp,16*1024*1024)!=bytes)throw std::runtime_error("storage verification failed");if(!MoveFileExW(temp.c_str(),path.c_str(),MOVEFILE_WRITE_THROUGH|(replace?MOVEFILE_REPLACE_EXISTING:0)))winrt::throw_last_error();}catch(...){if(created)DeleteFileW(temp.c_str());throw;}}
fs::path LegacyDirectory(const fs::path& folder){SafeDirectory(folder/L"Data");SafeDirectory(folder/L"Data"/L"Legacy");return folder/L"Data"/L"Legacy";}
void Archive(const fs::path& old,const std::string& expected){if(!fs::exists(old)||ReadBytes(old,8*1024*1024)!=expected)return;auto to=LegacyDirectory(old.parent_path())/(old.filename().wstring()+L"."+Unique()+L".legacy");if(!MoveFileExW(old.c_str(),to.c_str(),MOVEFILE_WRITE_THROUGH))winrt::throw_last_error();}
fs::path SettingsFile(const fs::path& folder){return !app.settings.empty()&&app.settings.parent_path()==folder?app.settings:folder/L"settings.json";}
JsonObject Root(const fs::path& file){if(!fs::exists(file))return JsonObject::Parse(winrt::to_hstring(SerializeViewerSettings(ViewerSettings{})));auto bytes=ReadBytes(file);ParseViewerSettings(bytes);return JsonObject::Parse(winrt::to_hstring(bytes));}
void SaveRoot(const fs::path& file,const JsonObject& value){auto bytes=winrt::to_string(value.Stringify());ParseViewerSettings(bytes);if(fs::exists(file)){auto old=ReadBytes(file);auto json=JsonObject::Parse(winrt::to_hstring(old));if(json.GetNamedNumber(L"version")<4){auto archive=LegacyDirectory(file.parent_path())/(L"settings-before-v062-"+Unique()+L".legacy");NewBytes(archive,old);}}Atomic(file,bytes);}
}
std::string ReadSettingsSection(const fs::path& folder,const wchar_t* key,const wchar_t* legacy,bool& fromLegacy){std::lock_guard<std::recursive_mutex> lock(storageMutex);fromLegacy=false;auto root=Root(SettingsFile(folder));if(root.HasKey(key))return winrt::to_string(root.GetNamedObject(key).Stringify());auto old=folder/legacy;if(fs::exists(old)){fromLegacy=true;return ReadBytes(old,8*1024*1024);}return {};}
void WriteSettingsSection(const fs::path& folder,const wchar_t* key,const std::string& bytes,const wchar_t* legacy){std::lock_guard<std::recursive_mutex> lock(storageMutex);auto value=JsonObject::Parse(winrt::to_hstring(bytes));auto file=SettingsFile(folder);auto root=Root(file);root.Insert(L"version",JsonValue::CreateNumberValue(4));root.Insert(key,value);SaveRoot(file,root);if(legacy&&*legacy){auto old=folder/legacy;if(fs::exists(old)&&ReadBytes(old,8*1024*1024)==bytes){try{Archive(old,bytes);}catch(...){/* The verified unified copy is authoritative; keep the old file on archive failure. */}}}}
void WriteViewerSettingsFile(const fs::path& file,const std::string& bytes){std::lock_guard<std::recursive_mutex> lock(storageMutex);auto root=Root(file),ui=JsonObject::Parse(winrt::to_hstring(bytes));for(auto pair:ui)root.Insert(pair.Key(),pair.Value());SaveRoot(file,root);}
fs::path AppDataFile(const fs::path& folder,const wchar_t* name){
    std::lock_guard<std::recursive_mutex> lock(storageMutex);auto old=folder/name,now=folder/L"Data"/name;
    try{SafeDirectory(folder/L"Data");if(!fs::exists(old))return now;
        if(fs::exists(now)){JsonObject::Parse(winrt::to_hstring(ReadBytes(now,8*1024*1024)));if(fs::exists(old)){auto bytes=ReadBytes(old,8*1024*1024);Archive(old,bytes);}return now;}
        if(fs::exists(old)){auto bytes=ReadBytes(old,8*1024*1024);JsonObject::Parse(winrt::to_hstring(bytes));Atomic(now,bytes,false);if(ReadBytes(now,8*1024*1024)!=bytes)throw std::runtime_error("data migration mismatch");Archive(old,bytes);}
        return now;
    }catch(...){if(fs::exists(now))return now;if(fs::exists(old))return old;return now;}
}
